              $this->aWfBuzon->clearAllReferences($deep);
            }
            if ($this->aRegional instanceof Persistent) {
              $this->aRegional->clearAllReferences($deep);
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collWfActividadTransicions instanceof PropelCollection) {
            $this->collWfActividadTransicions->clearIterator();
        }
        $this->collWfActividadTransicions = null;
        if ($this->collWfInstancias instanceof PropelCollection) {
            $this->collWfInstancias->clearIterator();
        }
        $this->collWfInstancias = null;
        $this->aTipoComRecibida = null;
        $this->aTipoComInterna = null;
        $this->aWfBuzon = null;
        $this->aRegional = null;
    }

    /**
     * return the string representation of this object
     *
     * @return string
     */
    public function __toString()
    {
        return (string) $this->exportTo(WfFlujoPeer::DEFAULT_STRING_FORMAT);
    }

    /**
     * return true is the object is in saving state
     *
     * @return boolean
     */
    public function isAlreadyInSave()
    {
        return $this->alreadyInSave;
    }

    /**
     * Catches calls to virtual methods
     */
    public function __call($name, $params)
    {
        
        // symfony_behaviors behavior
        if ($callable = sfMixer::getCallable('BaseWfFlujo:' . $name))
        {
          array_unshift($params, $this);
          return call_user_func_array($callable, $params);
        }


        return parent::__call($name, $params);
    }

}
